command -v 7z && command -v ark
QT_QPA_PLATFORM=offscreen ark --help 2>&1 | grep -E -- "--(batch|dialog|autodestination|autosubfolder|add|changetofirstpath|autofilename)" || true
ls /usr/lib64/qt6/plugins/kf6/kfileitemaction/ || true
test -f /usr/share/applications/classic7-7zip.desktop
test -f /usr/share/kio/servicemenus/classic7-7zip-extract.desktop
test -f /usr/share/kio/servicemenus/classic7-7zip-add.desktop
grep -q "^application/zip=classic7-7zip.desktop" /etc/xdg/mimeapps.list
grep -q "^compressfileitemaction=false" /etc/xdg/kservicemenurc
PYTHONPATH=/usr/lib/classic7 QT_QPA_PLATFORM=offscreen python3 -c "import photos_app; print(sorted(photos_app.picture_extensions()))"
/usr/bin/classic7-mail --help >/dev/null
# Network Connections and the network popup
test -x /usr/bin/classic7-network
