# --- Clean-up: one look, no doubles ---------------------------------------------------------
# Bazzite/Fedora ship many look-alike themes (Fedora, Valve Vapor/VGUI, Air, Oxygen, Breeze Dark,
# Breeze Twilight). Classic 7 is the look; the plain Breeze pieces stay as the fallback that
# Plasma and GTK apps need (lock screen, logout dialog, missing icons, GTK default).
for d in \
    /usr/share/plasma/look-and-feel/{com.valve.vapor.desktop,com.valve.vgui.desktop} \
    /usr/share/plasma/look-and-feel/org.fedoraproject.{fedora,fedoradark,fedoralight}.desktop \
    /usr/share/plasma/look-and-feel/{org.kde.air,org.kde.oxygen,org.kde.oxygenlight} \
    /usr/share/plasma/look-and-feel/{org.kde.breezedark.desktop,org.kde.breezetwilight.desktop} \
    /usr/share/plasma/desktoptheme/{Vapor,air,oxygen,breeze-dark,breeze-light} \
    /usr/share/color-schemes/{BreezeDark,BreezeClassic,Oxygen,OxygenCold,OxygenDark,VGUI,Vapor}.colors \
    /usr/share/themes/{Vapor,Emacs,Breeze-Dark} \
    /usr/share/icons/{oxygen,breeze-dark,Oxygen_Black,Oxygen_Blue,Oxygen_White,Oxygen_Yellow,Oxygen_Zion,KDE_Classic,Bluecurve}; do
    rm -rf "$d"
done
# Menu entries that duplicate a Classic 7 program (still installed and runnable by name)
#   Konsole -> Command Prompt, Bazzite Updater -> Classic 7 Update, Ark -> 7-Zip File Manager
for f in org.kde.konsole.desktop io.github.rfrench3.bazzite-updater.desktop org.kde.ark.desktop; do
    if [[ -f /usr/share/applications/$f ]]; then
        sed -i -e '/^NoDisplay=/d' -e '0,/^\[Desktop Entry\]/s//[Desktop Entry]\nNoDisplay=true/' "/usr/share/applications/$f"
    fi
done
# One plain text editor: KWrite (the Notepad; "notepad" in the Run dialog). Kate goes.
if rpm -q kate >/dev/null 2>&1; then
    dnf5 -y remove kate $(rpm -q kate-plugins >/dev/null 2>&1 && echo kate-plugins)
fi
if rpm -q kate >/dev/null 2>&1; then echo "ERROR: kate is still installed"; exit 1; fi
rpm -q kwrite
# what must remain
test -d /usr/share/plasma/look-and-feel/org.kde.breeze.desktop
test -d /usr/share/plasma/desktoptheme/default
test -f /usr/share/color-schemes/BreezeLight.colors
test -d /usr/share/icons/breeze
test -d /usr/share/themes/Breeze

# --- Login screen: SDDM with the Classic 7 theme ---------------------------------------------
# Fedora 44 switched KDE to Plasma Login Manager, whose look can't be changed (Breeze only).
# SDDM takes QML themes, so Classic 7 logs in through SDDM; Fedora still ships it.
if dnf5 -y install sddm sddm-wayland-plasma sddm-kcm; then
    systemctl disable plasmalogin.service || true
    systemctl enable --force sddm.service
    systemctl enable classic7-sddm-accounts.service classic7-sddm-keyboard.service classic7-sddm-keyboard.path
    chmod 0755 /usr/libexec/classic7-sddm-accounts /usr/libexec/classic7-sddm-keyboard
    # a Current= in the main file would override our conf.d file
    [[ -f /etc/sddm.conf ]] && sed -i 's/^\s*Current=/#Current=/' /etc/sddm.conf
    test -f /usr/share/sddm/themes/classic7/Main.qml
    test -x /usr/bin/sddm-greeter-qt6
    [[ "$(readlink -f /etc/systemd/system/display-manager.service)" == */sddm.service ]]
    grep -q '^Current=classic7' /etc/sddm.conf.d/classic7.conf
    systemctl is-enabled classic7-sddm-keyboard.service classic7-sddm-keyboard.path
else
    echo "WARNING: SDDM not available; keeping Plasma Login Manager (blue background only)"
fi

# --- Repositories ------------------------------------------------------------------------
# The installer ISO build (bootc-image-builder) reads the repos enabled in this image but
# looks up file:// GPG keys in its own container, which only has Fedora's keys. Third-party
# repos with local keys (Bazzite's terra-*, for example) make it fail, so switch them off.
# Installed systems update via the image, not via these repos (rpm-ostree can re-enable).
python3 - <<'PY'
import configparser, glob, os, platform, re
osrel = dict(l.rstrip("\n").split("=", 1) for l in open("/usr/lib/os-release") if "=" in l)
ver = osrel.get("VERSION_ID", "").strip('"')
subst = {"releasever": ver, "releasever_major": ver.split(".")[0], "basearch": platform.machine(), "arch": platform.machine()}
def expand(k):
    return re.sub(r"\$\{?(\w+)\}?", lambda m: subst.get(m.group(1), m.group(0)), k)
for path in glob.glob("/etc/yum.repos.d/*.repo"):
    cp = configparser.RawConfigParser(strict=False)
    try:
        cp.read(path)
    except configparser.Error:
        continue
    bad = set()
    for sec in cp.sections():
        if cp.get(sec, "enabled", fallback="1").strip() != "1":
            continue
        keys = re.split(r"[\s,]+", cp.get(sec, "gpgkey", fallback=""))
        local = [os.path.basename(expand(k)) for k in keys if k.startswith("file://")]
        if any(not n.startswith("RPM-GPG-KEY-fedora") for n in local):
            bad.add(sec)
    if not bad:
        continue
    out, sec = [], None
    for line in open(path):
        m = re.match(r"\s*\[(.+)\]\s*$", line)
        if m:
            sec = m.group(1)
        elif sec in bad and re.match(r"\s*enabled\s*=\s*1\s*$", line):
            line = "enabled=0\n"
        out.append(line)
    open(path, "w").writelines(out)
    print(f"Disabled third-party repos with local GPG keys in {path}: {', '.join(sorted(bad))}")
PY
